<template><div class="focus-timer"><span class="m-badge m-badge--info">{{ status==='running'?'正在专注':status==='paused'?'已暂停':'准备开始' }}</span><div class="focus-clock" role="timer" aria-label="专注剩余时间">{{ timeLabel }}</div><label v-if="!active" class="m-field"><span>这次想专注多久？</span><select :value="minutes" class="m-input" aria-label="专注时长" @change="emit('update:minutes',Number(($event.target as HTMLSelectElement).value))"><option v-for="n in [10,15,25,45]" :key="n" :value="n">{{ n }} 分钟</option></select></label><div class="focus-timer-actions"><button v-if="!active" class="m-btn m-btn--primary" :disabled="busy" @click="emit('action','start')"><Play :size="18"/>开始专注</button><template v-else><button class="m-btn m-btn--primary" :disabled="busy" @click="emit('action',status==='paused'?'resume':'pause')"><component :is="status==='paused'?Play:Pause" :size="18"/>{{ status==='paused'?'继续':'暂停' }}</button><button class="m-btn m-btn--ghost" :disabled="busy" @click="emit('action','finish')"><Square :size="16"/>结束并保存</button></template></div><button v-if="active" class="workspace-text-action" :disabled="busy" @click="emit('action','reset')"><RotateCcw :size="14"/> 重置这一段</button><p>记录的是服务器计时经过的时间，不会将它等同于学习效果。</p></div></template>
<script setup lang="ts">
import { computed } from 'vue'
import { Pause, Play, RotateCcw, Square } from 'lucide-vue-next'
const props=defineProps<{seconds:number;minutes:number;status?:string;busy:boolean}>(),emit=defineEmits<{'update:minutes':[minutes:number];action:[action:string]}>(),active=computed(()=>['running','paused'].includes(props.status||'')),timeLabel=computed(()=>`${String(Math.floor(Math.max(0,props.seconds)/60)).padStart(2,'0')}:${String(Math.max(0,props.seconds)%60).padStart(2,'0')}`)
</script>
<style scoped>.focus-timer{display:grid;justify-items:center;gap:20px;text-align:center;padding:12px 0}.focus-clock{display:grid;place-items:center;width:240px;height:240px;max-width:100%;border:2px solid var(--m-primary-border);border-top-color:var(--m-primary);border-right-color:var(--m-violet);border-radius:50%;font-size:56px;font-weight:550;letter-spacing:-2px;background:var(--m-violet-soft)}.focus-timer>.m-field{width:min(100%,280px);text-align:left}.focus-timer-actions{display:flex;gap:12px;justify-content:center;width:100%;flex-wrap:wrap}.focus-timer-actions>.m-btn{flex:1;max-width:280px}.focus-timer>p{font-size:12px;color:var(--m-text-faint);line-height:1.8;margin:0;max-width:30em}</style>
